"""Principles of inference and boundary (stated-not-proved) nodes."""
from nodespec import N

N("sufficiency_principle", "regime", "principles",
  "The sufficiency principle: if T is a sufficient statistic for theta and T(x) = T(y) for two data sets x, y, then x and y must lead to the same inference about theta.",
  parseable="T sufficient  and  T(x) = T(y)   =>   inference from x  =  inference from y",
  symbols={"'the same inference'": "the same point estimate, interval, test decision, posterior -- whatever the inferential output is"},
  tcn="A normative principle, not a theorem. It is very widely accepted (nearly all standard methods obey it) and follows from the factorization of the likelihood through T.",
  status_label="heuristic",
  regime="exact",
  hyps=[],
  proof=("the likelihood function depends on the data only through T (Neyman-Fisher factorization), and most inference schools agree inference should depend on the data only through the likelihood-relevant part",
         "neyman_fisher_factorization", "cited", None),
  spec=["obeyed by MLE, Bayes, UMVUE, LRT -- all are functions of any sufficient statistic",
        "the basis for reducing a whole sample to (Xbar, S^2) in normal-theory inference with no loss"],
  cxd={"none_all_hypotheses_essential": "the principle is a stance; there is nothing to 'drop'. A method violating it (e.g. one depending on the order in which iid data arrived) would be regarded as defective."},
  misuse=["confusing it with the (much stronger, more contested) likelihood principle",
          "assuming a method is 'good' merely because it obeys sufficiency -- it is a minimal requirement"],
  related={"uses": ["neyman_fisher_factorization", "sufficiency"], "required_by": ["likelihood_principle"]},
  sources=["birnbaum_1962", "berger_wolpert_likelihood_principle"])

N("conditionality_principle", "regime", "principles",
  "The conditionality principle: if the experiment actually performed was selected by a random mechanism ANCILLARY to theta (a mixture of experiments), then inference should be conditional on which experiment was in fact run, ignoring the ones that were not.",
  parseable="experiment E chosen by an ancillary randomizer   =>   condition on E = e actually observed",
  symbols={"a mixture experiment": "flip a coin; heads -> measure with the precise instrument, tails -> the crude one",
           "the ancillary statistic": "which experiment was chosen -- its law is free of theta"},
  tcn="A normative principle. It says the relevant reference set for a frequentist calculation is 'repetitions of the experiment I actually did', not 'repetitions of the random choice of experiment'. Widely (not universally) accepted.",
  status_label="heuristic",
  regime="exact",
  hyps=[],
  proof=("the choice of experiment carries no information about theta (ancillary); averaging over unrealized experiments dilutes the analysis with irrelevant variability",
         "ancillary_statistic", "cited", None),
  spec=["the classic example (Cox 1958): a measurement is made by a randomly chosen instrument of known, different precisions -- report the SE of the instrument used, not a mixture SE",
        "conditioning on the observed information (rather than expected) in likelihood inference is a conditionality-principle move (Efron-Hinkley)",
        "conditioning on ancillary configuration statistics in location-scale models -> exact conditional inference (Fisher, Fraser)"],
  cxd={"the_selector_is_ancillary": "if which 'experiment' is run depends on theta (informative sampling, response-adaptive designs), conditioning on it can bias the analysis -- the principle applies only to theta-ancillary selection"},
  misuse=["conditioning on a statistic that is only approximately ancillary and ignoring the approximation",
          "using it to justify ignoring a genuinely informative selection mechanism"],
  related={"uses": ["ancillary_statistic", "iid_sample"], "required_by": ["likelihood_principle"]},
  sources=["cox_1958", "birnbaum_1962", "berger_wolpert_likelihood_principle"])

N("likelihood_principle", "regime", "principles",
  "The likelihood principle: all the evidence about theta contained in the data x is captured by the likelihood function L(theta; x), up to a positive multiplicative constant; two experiments yielding proportional likelihoods for theta warrant identical inference. Birnbaum's theorem: sufficiency + conditionality together IMPLY the likelihood principle.",
  parseable="L(theta; x_1) proportional to L(theta; x_2)  (as functions of theta)   =>   identical inference about theta;   and  [sufficiency + conditionality]  =>  [likelihood principle]  (Birnbaum 1962)",
  symbols={"proportional": "L(theta; x_1) = c(x_1, x_2) L(theta; x_2) for all theta, with c > 0 free of theta",
           "the tension": "Bayesian and pure-likelihood methods obey it; frequentist methods using tail areas (p-values, confidence intervals, unbiasedness) generally VIOLATE it"},
  tcn="A strong, contested normative principle. Its bite: the stopping rule of a sequential experiment is irrelevant to the evidence (only the observed likelihood matters), which conflicts with frequentist error control. Birnbaum's derivation from two mild-seeming principles is the surprise.",
  status_label="heuristic",
  regime="bayesian",
  hyps=[],
  proof=("Birnbaum 1962: the sufficiency principle and the conditionality principle jointly entail the likelihood principle; the proof is a short combinatorial argument on mixture experiments (though its premises have been re-examined, e.g. Evans 2013, Mayo 2014)",
         "sufficiency_principle", "cited", None),
  spec=["binomial vs negative-binomial sampling giving the same observed (successes, failures): the likelihoods are proportional, so a likelihoodist / Bayesian analysis is identical -- but the frequentist p-value DIFFERS (different sample spaces)",
        "sequential trials: under the likelihood principle, 'we stopped when it looked significant' does not change the evidence in the observed data -- diametrically opposed to frequentist alpha-spending",
        "fully obeyed by Bayesian posteriors and by pure-likelihood (Royall) inference"],
  cxd={"accepting_both_premises_unrestrictedly": "the principle is CONTESTED. Frequentists reject it (or reject one of Birnbaum's premises) precisely because it outlaws pre-data error-rate control; Mayo (2014) and others dispute the theorem's premises. This node states the principle and the theorem; it does not adjudicate."},
  misuse=["citing the likelihood principle as settled fact -- it is a genuine, live foundational dispute",
          "using it to dismiss all concern about stopping rules / multiplicity in a frequentist analysis (which does not accept the principle)"],
  related={"uses": ["likelihood_function", "sufficiency_principle", "conditionality_principle"],
           "equivalent_to": ["sufficiency_principle"]},
  sources=["birnbaum_1962", "berger_wolpert_likelihood_principle", "mayo_2014"])

N("le_cam_lan_theory", "theorem", "principles",
  "Local asymptotic normality (LAN): for a regular parametric model, the log-likelihood ratio for local parameters theta_0 + h/sqrt(n) vs theta_0 admits the expansion log [ L(theta_0 + h/sqrt(n)) / L(theta_0) ] = h^T Delta_n - (1/2) h^T I(theta_0) h + o_{P_{theta_0}}(1), where Delta_n -> N(0, I(theta_0)). The local experiments converge to a single Gaussian shift experiment N(h, I(theta_0)^{-1}).",
  parseable="log LR(theta_0 + h/sqrt n : theta_0) = h^T Delta_n - (1/2) h^T I h + o_p(1),   Delta_n -->^d N(0, I)",
  symbols={"h": "the local parameter (a direction and magnitude of a 1/sqrt(n) perturbation)",
           "Delta_n = (1/sqrt n) sum score(X_i; theta_0)": "the normalized score, the LAN 'central sequence'",
           "the limit experiment": "observing one draw from N(h, I(theta_0)^{-1}) -- everything asymptotic reduces to this"},
  tcn="The organizing theorem of modern asymptotic statistics (Le Cam). It says all regular parametric models look locally like a Gaussian location problem, so optimality questions (efficient estimation, most powerful testing) are answered ONCE, in the Gaussian shift experiment, and transferred back. Boundary node: stated, cited.",
  status_label="proved_theorem",
  regime="asymptotic",
  hyps=["log_likelihood_smooth", "fisher_information_positive_definite", "true_parameter_interior"],
  proof=("Taylor / differentiability-in-quadratic-mean expansion of the log-likelihood ratio; the cross term is the central sequence, converging by the CLT",
         "mle_asymptotic_normality", "cited",
         "CITED -- Le Cam 1960; van der Vaart Asymptotic Statistics Ch. 7-9. Not formalized."),
  spec=["MLE asymptotic normality, Wilks' theorem, and the asymptotic equivalence of the Wald/score/LR tests are all corollaries of LAN + properties of the Gaussian shift experiment",
        "contiguity (Le Cam's lemmas) lets you compute limiting power under alternatives from behaviour under the null",
        "semiparametric efficiency theory (LAN with an infinite-dimensional nuisance) generalizes it"],
  cxd={"regular_model": "non-LAN models: uniform(0, theta) is locally asymptotically EXPONENTIAL (LAE, rate n); some models are locally asymptotically MIXED normal (LAMN, e.g. explosive AR, some diffusions). The Gaussian-shift reduction and its optimality conclusions do not apply.",
       "fixed_dimension": "increasing-dimension / nonparametric models need the infinite-dimensional LAN theory and have their own (slower) efficiency bounds"},
  misuse=["applying LAN-based efficiency claims to a non-regular model (unit-root tests are the classic cautionary tale -- the limit is not normal)",
          "assuming local (h/sqrt n) optimality implies good behaviour against fixed alternatives"],
  related={"uses": ["information_equality", "prob_clt", "mle_asymptotic_normality"],
           "required_by": ["hajek_convolution_theorem", "local_asymptotic_minimax"]},
  sources=["le_cam_asymptotic_methods", "van_der_vaart_asymptotic"])

N("hajek_convolution_theorem", "theorem", "principles",
  "In a LAN model, the limit distribution of ANY regular estimator sequence theta_hat_n (one whose local limit law does not depend on the local parameter h) can be written as a convolution N(0, I(theta_0)^{-1}) * M for some distribution M; the efficient (minimum-dispersion) regular estimator has M = delta_0 and limit exactly N(0, I(theta_0)^{-1}).",
  parseable="regular estimator  =>  its local limit law  =  N(0, I(theta_0)^{-1})  *  M   (M some noise distribution)",
  symbols={"regular": "the local limit law is the same for every local parameter h (rules out Hodges superefficiency)",
           "* M": "an extra independent 'noise' term -- so the efficient estimator's limit is a lower bound in the convolution order"},
  tcn="The rigorous, estimator-free statement of 'you cannot beat the Fisher-information bound' -- replacing the CRLB's unbiasedness assumption with regularity. Boundary node: stated, cited. It is why 'asymptotically efficient' = 'asymptotic variance I^{-1}' is the right definition.",
  status_label="proved_theorem",
  regime="asymptotic",
  hyps=[],
  proof=("Hajek 1970 / Le Cam; the LAN structure + the regularity of the estimator force the convolution representation via a characteristic-function argument in the Gaussian shift experiment",
         "le_cam_lan_theory", "cited",
         "CITED -- Hajek 1970; van der Vaart Ch. 8. Not formalized."),
  spec=["the MLE (M = delta_0) is efficient; a regular but inefficient estimator has M nondegenerate, i.e. strictly more spread",
        "removes the Hodges superefficiency loophole: superefficient estimators are NOT regular (their local limit law depends on h)",
        "the semiparametric analogue bounds regular estimators of a finite-dimensional functional in a model with an infinite-dimensional nuisance"],
  cxd={"regularity_of_the_estimator": "drop it and Hodges' estimator formally 'beats' I^{-1} at a point -- but only by being non-regular (badly behaved just off that point), which the theorem's hypothesis excludes",
       "LAN_model": "in LAMN models the bound involves a random information and the statement changes (mixed-normal limits)"},
  misuse=["citing it to claim no estimator can have smaller asymptotic variance than I^{-1} anywhere -- superefficiency on a null set IS possible, it just cannot be regular",
          "applying it in non-LAN settings"],
  related={"uses": ["le_cam_lan_theory", "asymptotic_efficiency"], "strengthens": ["cramer_rao_lower_bound"]},
  sources=["hajek_1970", "van_der_vaart_asymptotic"])

N("local_asymptotic_minimax", "theorem", "principles",
  "The local asymptotic minimax (LAM / Hajek-Le Cam) theorem: in a LAN model, for any estimator sequence and any bowl-shaped loss l, liminf_n sup_{|h| <= c} E_{theta_0 + h/sqrt n}[ l( sqrt(n)(theta_hat_n - theta_0 - h/sqrt n) ) ] >= E[ l(Z) ], where Z ~ N(0, I(theta_0)^{-1}), and the bound is attained by the MLE. No estimator can beat the Fisher-information risk locally, in a minimax sense, without any regularity assumption on the estimator.",
  parseable="liminf_n  sup_{|h| <= c}  E_{theta_0 + h/sqrt n}[ l( sqrt n (theta_hat_n - theta_n) ) ]   >=   E[ l(Z) ],   Z ~ N(0, I^{-1})",
  symbols={"bowl-shaped loss": "l(x) = l(-x), sublevel sets convex (squared error, absolute error, 0-1)",
           "the local minimax over |h| <= c": "shrinking neighbourhoods, then c -> inf"},
  tcn="The strongest and cleanest optimality statement in the classical theory: no regularity on the estimator at all, and it rules out ALL superefficiency (Hodges' estimator has local minimax risk that BLOWS UP as c grows). Boundary node: stated, cited.",
  status_label="proved_theorem",
  regime="asymptotic",
  hyps=[],
  proof=("reduce to the Gaussian shift limit experiment (LAN) and apply the minimax property of the Gaussian location estimator for bowl-shaped loss (Anderson's lemma)",
         "le_cam_lan_theory", "cited",
         "CITED -- Hajek 1972; van der Vaart Ch. 8. Not formalized."),
  spec=["squared-error loss: the local minimax risk bound is tr(I(theta_0)^{-1}), matched by the MLE",
        "Hodges' superefficient estimator: efficient at theta_0 but its local minimax risk over |h| <= c tends to infinity as c grows -- superefficiency is paid for by terrible risk nearby",
        "the semiparametric LAM bound governs efficient estimation of a functional in the presence of a nonparametric nuisance"],
  cxd={"bowl_shaped_loss": "for non-bowl-shaped (asymmetric) loss the bound changes and Anderson's lemma does not apply directly",
       "LAN": "non-regular models have their own (different, often faster or slower) minimax rates -- see minimax_rate"},
  misuse=["reading it as a statement about a fixed theta (it is local / minimax over shrinking neighbourhoods)",
          "assuming attainment implies the MLE is best at every finite n"],
  related={"uses": ["le_cam_lan_theory", "cramer_rao_lower_bound"], "required_by": ["minimax_rate"]},
  sources=["hajek_1972", "van_der_vaart_asymptotic"])

N("donsker_theorem", "theorem", "principles",
  "Donsker's theorem (the functional CLT for the empirical process): the empirical process G_n = sqrt(n)(F_hat_n - F) converges in distribution, in the space of bounded functions on R with the sup metric, to a tight mean-zero Gaussian process G -- the F-Brownian bridge, with Cov(G(s), G(t)) = F(s and t) - F(s)F(t). More generally, the empirical process indexed by a Donsker class of functions converges to a Gaussian process.",
  parseable="G_n = sqrt(n)(F_hat_n - F)  -->^d  G,   an F-Brownian bridge   (in ell^inf(R), sup metric)",
  symbols={"G_n": "the empirical process", "G": "the limiting Gaussian process (Brownian bridge composed with F)",
           "a Donsker class": "a function class over which this uniform CLT holds (finite uniform entropy / bracketing)"},
  tcn="The process-level strengthening of the pointwise CLT for F_hat_n, and the rate-level strengthening of Glivenko-Cantelli. It is the analytic engine behind the limiting null distributions of the Kolmogorov-Smirnov and Cramer-von Mises statistics, and behind the functional delta method (hence bootstrap consistency for smooth functionals). Boundary node: stated, cited.",
  status_label="proved_theorem",
  regime="distribution_free",
  hyps=[],
  proof=("finite-dimensional CLT + asymptotic tightness (stochastic equicontinuity) of the empirical process; for general classes, chaining under a uniform-entropy or bracketing-entropy condition",
         "glivenko_cantelli", "cited",
         "CITED -- Donsker 1952; van der Vaart-Wellner 1996. Not formalized."),
  spec=["sup_x |G_n(x)| -> sup |Brownian bridge| gives the Kolmogorov-Smirnov limiting distribution (Kolmogorov's formula)",
        "int G_n^2 dF -> int (Brownian bridge)^2 gives the Cramer-von Mises limit",
        "the functional delta method: for Hadamard-differentiable T, sqrt(n)(T(F_hat_n) - T(F)) -> T'_F(G) -- the source of asymptotic normality for quantiles, trimmed means, L-statistics, and the bootstrap's validity"],
  cxd={"Donsker_class": "the class of ALL indicator functions of finite sets is not Donsker -- and neither is a class with infinite uniform entropy; over such classes the empirical process does not converge (it is not even tight). This is what separates 'nice' nonparametric problems from genuinely hard ones.",
       "iid": "dependent data need mixing conditions and give a different (long-range vs short-range) limit"},
  misuse=["assuming a supremum functional of the empirical process has a normal limit -- it has an extreme-value / Brownian-bridge-supremum limit",
          "invoking Donsker for a function class whose complexity (entropy) has not been checked"],
  related={"uses": ["glivenko_cantelli", "prob_clt", "empirical_cdf"], "strengthens": ["glivenko_cantelli", "dvoretzky_kiefer_wolfowitz"]},
  sources=["donsker_1952", "van_der_vaart_wellner", "billingsley_convergence_of_probability_measures"])

N("minimax_rate", "regime", "principles",
  "For a nonparametric estimation problem (estimating a function f in a smoothness class F, e.g. densities or regression functions with beta bounded derivatives), the minimax risk inf_{f_hat} sup_{f in F} E ||f_hat - f||^2 decays at a rate SLOWER than n^{-1}: typically n^{-2 beta / (2 beta + d)} for beta-smooth functions in d dimensions. The rate is a property of the problem, achieved (up to constants / logs) by an appropriately tuned estimator and unimprovable by any estimator.",
  parseable="inf_{f_hat} sup_{f in F_beta}  E || f_hat - f ||^2   asymptotic to   n^{ -2 beta / (2 beta + d) }",
  symbols={"beta": "the assumed smoothness (number of derivatives / Holder exponent) of the target function",
           "d": "the dimension of the function's domain",
           "the exponent 2 beta/(2 beta + d)": "< 1, approaching 1 as beta -> inf (smoother => closer to parametric rate)"},
  tcn="An asymptotic minimax RATE statement, with matching upper (a constructive estimator) and lower (Fano / Assouad / Le Cam two-point) bounds. It quantifies 'nonparametric problems need more data' and pins the price of dimension (the curse: rate collapses as d grows) and the reward of smoothness. Boundary node: stated, cited.",
  status_label="proved_theorem",
  regime="asymptotic",
  hyps=[],
  proof=("upper bound: bias-variance analysis of a kernel / spline / wavelet estimator at the optimal bandwidth (kde_bias_variance_tradeoff); lower bound: reduce to a many-hypothesis testing problem and apply Fano's inequality or Assouad's lemma",
         "kde_bias_variance_tradeoff", "cited",
         "CITED -- Stone 1980, 1982; Tsybakov Introduction to Nonparametric Estimation. The h ~ n^{-1/(2 beta + d)} balancing is the KDE-node computation; the lower bound is the cited analytic content."),
  spec=["density estimation, twice-differentiable (beta = 2), d = 1: rate n^{-4/5} -- matches the KDE MISE (kde_bias_variance_tradeoff)",
        "nonparametric regression with beta-smooth mean, d covariates: n^{-2 beta/(2 beta + d)}",
        "d = 10, beta = 2: rate n^{-4/14} approx n^{-0.29} -- to halve the error you need ~11x the data (the curse of dimensionality); this is why structure (additivity, sparsity, single-index) is imposed"],
  cxd={"the_smoothness_class_is_correct": "if f is actually rougher than assumed (fewer derivatives) the tuned estimator is inconsistent at the claimed rate; adaptive estimators (Lepski, wavelet thresholding) achieve the right rate WITHOUT knowing beta, at a log-factor cost",
       "no_extra_structure": "under sparsity or a low-dimensional structure the effective d is much smaller and near-parametric rates return -- the entire premise of high-dimensional statistics"},
  misuse=["expecting parametric-rate confidence intervals from a nonparametric fit",
          "comparing a parametric model's n^{-1/2} and a nonparametric model's n^{-2/5} error as if the models were estimating the same thing (the parametric one also risks bias from misspecification)",
          "ignoring the curse of dimensionality when d is more than 3-4"],
  related={"uses": ["kde_bias_variance_tradeoff", "local_asymptotic_minimax"], "generalizes_from": ["cramer_rao_lower_bound"]},
  sources=["stone_1980", "tsybakov_nonparametric", "gine_nickl_mathematical_foundations"])
